page.css:
[style]
	body {font-family: tahoma,helvetica; font-size: 10pt ; background: #f0f0f0; color: black}
	li {font-family: tahoma,helvetica; font-size: 8pt }
	th {font-family: tahoma,helvetica; font-size: 8pt ; background: #08245a; font-weight: normal; color: white}
	td.subtitle {font-family: tahoma,helvetica; background: #a5cff7; font-size: 8pt ; color: white}
	td.footer {font-family: tahoma,helvetica; background: #e0e0e0; font-size: 8pt ; color: #5050e2}
	td.summary {font-family: tahoma,helvetica; font-size: 8pt ; background: #d6ebff; font-style: italic; color: black}
	td.total {font-family: tahoma,helvetica; font-size: 8pt ; background: #7070e2; font-weight: bold; color: white}
	td.tool {font-family: tahoma,helvetica; font-size: 8pt ; background: #a5cff7; color: #08245a}
	td.alert {font-family: tahoma,helvetica; font-size: 8pt ; background: #FF0000; font-weight: bold; color: white}
	td {font-family: tahoma,helvetica; background: white; font-size: 8pt ; color: black}
	h1 {font-family: tahoma,helvetica; font-size: 16pt ; color: #08245a}
	h2 {font-family: tahoma,helvetica; font-size: 14pt ; color: #08245a}
	h3 {font-family: tahoma,helvetica; font-size: 12pt ; color: #08245a}
	h4 {font-family: tahoma,helvetica; font-size: 10pt ; color: #08245a}
	h5 {font-family: tahoma,helvetica; font-size: 8pt ; color: #08245a}
	input {font-family: tahoma,helvetica; font-size: 8pt}
	input.tool {font-family: tahoma,helvetica; background: #bccede;font-size: 8pt}
	input.navig {width:24px; font-family: tahoma,helvetica; background: #bccede;font-size: 8pt}
	input.export {width:31px; font-family: tahoma,helvetica; background: #bccede;font-size: 8pt}
	font {font-family: tahoma,helvetica; font-size: 10pt ; color: #140181}
	a {text-decoration: none; font-family: tahoma,helvetica; font-size: 10pt ; background:#f0f0f0; color: #FF6500}
	a:hover {text-decoration: underlined; font-family: tahoma,helvetica; font-size: 10pt ; background:white; color: #FF6500}
	a.menu {text-decoration: none; font-family: tahoma,helvetica; font-size: 8pt ; background:white; color: #FF6500}
	a.menu:hover {text-decoration: none; font-family: tahoma,helvetica; font-size: 8pt ; background:#FF6500; color: white}
	a.orderby {text-decoration: none; font-family: tahoma,helvetica; background: #08245a; font-weight: normal; font-size: 8pt; color: white}
	a.orderby:hover {text-decoration: none; font-family: tahoma,helvetica; background: #08245a; font-weight: normal; font-size: 8pt; color: #ff6500}
[/style]

menu.bottombar_start:
[html]
	[head]
		[style]
			body {font-family: tahoma,helvetica; font-size: 8pt ; background: #FF6666; color: white; font-weight: bold; }
			table {font-size: 8pt ; color: white}
			td {font-family: tahoma,helvetica; font-size: 8pt ; color: white}
			input {font-family: tahoma,helvetica; font-size: 7pt}
			input.sel {font-family: tahoma,helvetica; color: #ff6500; font-weight: bold; font-size: 7pt}
			a.menu {text-decoration: none; font-family: tahoma,helvetica; font-size: 8pt ; color: white}
			a.menu:hover {text-decoration: none; font-family: tahoma,helvetica; font-size: 8pt ; color: #23238E}
		[/style]
	[/head]
	[body leftmargin=1 topmargin=1]

menu.menu_start:
[html]
	[head]
		[style]
			body {font-family: tahoma,helvetica; font-size: 9pt ; background: #FFFFFF; color: black}
			select {font-family: tahoma,helvetica; font-size: 9pt}
			input {font-family: tahoma,helvetica; font-size: 9pt}
			input.sel {font-family: tahoma,helvetica; color: blue; font-weight: bold; font-size: 9pt}
			a.menu {text-decoration: none; font-family: tahoma,helvetica; font-size: 9pt ; color: #000000}
			a.menu:hover {text-decoration: none; font-family: tahoma,helvetica; font-weight: bold; font-size: 9pt ; color: #FF6500}
			a {text-decoration: none; font-family: tahoma,helvetica; font-size: 8pt ; color: #000000}
			a:hover {text-decoration: none; font-family: tahoma,helvetica; font-size: 8pt ; color: #000000}
		[/style]
	[/head]
	[body leftmargin=1 topmargin=1]
